import{_ as t,o as n,c as l,am as a}from"./chunks/framework._FJXuPhs.js";const d=JSON.parse('{"title":"MCP Java SDK：标准与架构全面分析","description":"","frontmatter":{"title":"MCP Java SDK：标准与架构全面分析","excerpt":"摘要","date":"2026-01-04 16:53:43","updated":"2026-01-04 16:53:43"},"headers":[],"relativePath":"框架/AI 框架/Spring AI/MCP Java SDK：标准与架构全面分析.md","filePath":"框架/AI 框架/Spring AI/MCP Java SDK：标准与架构全面分析.md","lastUpdated":null}'),o={name:"框架/AI 框架/Spring AI/MCP Java SDK：标准与架构全面分析.md"};function r(i,s,e,g,p,h){return n(),l("div",null,[...s[0]||(s[0]=[a(`<blockquote><p><strong>内容概览：</strong></p><ol><li>什么是 MCP Java SDK？</li><li>MCP 的三层架构介绍</li><li>核心功能与模块（工具、资源、提示词等）</li><li>重点传输协议解读及场景应用</li><li>Spring AI 与 MCP 集成方式</li></ol></blockquote><hr><h3 id="什么是-mcp-java-sdk" tabindex="-1">什么是 MCP Java SDK ？ <a class="header-anchor" href="#什么是-mcp-java-sdk" aria-label="Permalink to &quot;什么是 MCP Java SDK ？&quot;">​</a></h3><p>Spring AI 框架用于实现 MCP 协议的上层架构实现。</p><p><strong>MCP Java SDK</strong> 的实现采用了<strong>三层架构</strong>设计，这种架构将应用逻辑、会话管理和底层传输进行了明确的解耦，以提高系统的可维护性和灵活性,。</p><p>以下是该架构的详细组成：</p><h4 id="_1-客户端-服务器层-顶部" tabindex="-1">1. 客户端/服务器层 (顶部) <a class="header-anchor" href="#_1-客户端-服务器层-顶部" aria-label="Permalink to &quot;1. 客户端/服务器层 (顶部)&quot;">​</a></h4><p>这一层处于架构的最顶端，直接面向开发者，负责处理主要的<strong>应用逻辑</strong>和<strong>协议操作</strong>,。</p><ul><li><strong>McpClient</strong>：负责管理客户端的所有操作以及与服务器的连接,。</li><li><strong>McpServer</strong>：负责处理服务器端的协议操作并响应来自客户端的请求,。 这两个核心组件在运行时都会利用其下方的“会话层”来执行具体的通信管理任务,。</li></ul><h4 id="_2-会话层-中间层" tabindex="-1">2. 会话层 (中间层) <a class="header-anchor" href="#_2-会话层-中间层" aria-label="Permalink to &quot;2. 会话层 (中间层)&quot;">​</a></h4><p>中间层起到了承上启下的作用，主要负责管理<strong>通信模式</strong>并<strong>维护连接状态</strong>,。</p><ul><li><strong>McpSession</strong>：这是核心的会话管理接口,。</li><li><strong>具体实现</strong>：针对客户端和服务器的不同需求，SDK 提供了 <strong>McpClientSession</strong> 和 <strong>McpServerSession</strong> 两种特定的实现,。</li></ul><h4 id="_3-传输层-底部" tabindex="-1">3. 传输层 (底部) <a class="header-anchor" href="#_3-传输层-底部" aria-label="Permalink to &quot;3. 传输层 (底部)&quot;">​</a></h4><p>传输层是整个架构的基石，负责最底层的<strong>消息传输</strong>和<strong>数据序列化</strong>,。</p><ul><li><strong>McpTransport</strong>：该组件专门管理 <strong>JSON-RPC</strong> 消息的序列化与反序列化,。</li><li><strong>多协议支持</strong>：它为各种高层次的沟通提供基础支持，能够兼容多种传输机制，包括 <strong>STDIO</strong>（标准输入输出）、<strong>HTTP/SSE</strong> 以及最新的 <strong>Streamable-HTTP</strong> 等,。</li></ul><hr><blockquote><p><strong>比喻理解：</strong> 如果把 MCP Java SDK 比作一个<strong>邮政系统</strong>：</p></blockquote><ul><li><strong>顶部层</strong>就像是“<strong>发件人和收件人</strong>”，他们关注的是信件的内容和目的。</li><li><strong>中间层</strong>就像是“<strong>邮局分拣中心</strong>”，负责管理信件的状态（是否挂号、是否妥投）并建立收发双方的联系。</li><li><strong>底部层</strong>则是“<strong>运输车队和道路</strong>”，无论信件是通过卡车（STDIO）、火车（SSE）还是飞机（Streamable-HTTP）运输，它们只负责将信件打成包裹（序列化）并安全送达,。</li></ul><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A[客户端/服务器层] --&gt; B[会话层]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt; C[传输层（JSON-RPC 序列化）]</span></span></code></pre></div><blockquote><p><strong>总结</strong>：三层架构通过清晰划分职责，降低开发复杂性，同时提升了架构的模块化和扩展性。</p></blockquote><hr><h3 id="声明式注解" tabindex="-1">声明式注解 <a class="header-anchor" href="#声明式注解" aria-label="Permalink to &quot;声明式注解&quot;">​</a></h3><p>通过 Spring AI 的声明式集成，开发者极大地简化 MCC 的开发工作。</p><ul><li><strong>核心注解</strong>：Spring AI 提供了 <code>@McpTool</code>（工具）、<code>@McpResource</code>（资源）、<code>@McpPrompt</code>（提示词）等注解。</li><li><strong>自动生成</strong>：<code>@McpTool</code> 会自动根据方法参数生成 <strong>JSON 模式 (JSON Schema)</strong>，模型利用该模式理解如何调用工具。</li></ul><p><strong>优势</strong>：这种声明式方法大幅减少了样板代码，提高了代码的可维护性，并能通过 Spring Boot 的自动配置实现 Bean 的<strong>自动检测与注册</strong>。</p><hr><h3 id="mcp-的三大核心功能" tabindex="-1">MCP 的三大核心功能 <a class="header-anchor" href="#mcp-的三大核心功能" aria-label="Permalink to &quot;MCP 的三大核心功能&quot;">​</a></h3><ul><li>工具 Tools <ul><li>允许服务器暴露功能供大语言模型（LLM）使用。</li></ul></li><li>资源 Resources <ul><li>提供标准化的数据暴露方式。</li></ul></li><li>提示词 Prompts <ul><li>定义与优化 AI 用户交互的提示。</li><li>同时支持： <ul><li><strong>自动补全 (Completions)</strong></li><li><strong>结构化日志 (Logging)</strong> 和 <strong>进度跟踪 (Progress)</strong>。</li></ul></li></ul></li></ul><hr><h3 id="灵活的传输机制与协议" tabindex="-1">灵活的传输机制与协议 <a class="header-anchor" href="#灵活的传输机制与协议" aria-label="Permalink to &quot;灵活的传输机制与协议&quot;">​</a></h3><p>模型上下文协议（MCP）支持多种传输协议，为不同的应用环境提供了极高的灵活性。</p><p>以下是四种核心传输机制的详细分析：</p><h4 id="四种传输机制及应用场景分析" tabindex="-1"><strong>四种传输机制及应用场景分析</strong> <a class="header-anchor" href="#四种传输机制及应用场景分析" aria-label="Permalink to &quot;**四种传输机制及应用场景分析**&quot;">​</a></h4><ol><li><strong>STDIO（标准输入输出）</strong><ul><li><strong>技术细节</strong>：这是一种进程内协议，通信通过标准输入和标准输出进行，无需额外的网络依赖。</li><li><strong>适用场景</strong>：主要用于<strong>本地主机应用</strong>、<strong>命令行工具</strong>（CLI）或<strong>桌面工具</strong>，非常适合开发者的局部通信与快速测试。</li></ul></li><li><strong>SSE（服务器发送事件）</strong><ul><li><strong>技术细节</strong>：基于 HTTP 的实时事件协议，服务器作为独立进程运行，能够处理多个客户端连接。</li><li><strong>适用场景</strong>：适用于需要服务器向客户端推送实时事件的传统 Web 环境。</li></ul></li><li><strong>可流式 HTTP（Streamable-HTTP）</strong><ul><li><strong>技术细节</strong>：该协议<strong>取代了 SSE 传输</strong>，支持通过 HTTP POST 和 GET 请求进行持久连接管理和实时通知。</li><li><strong>适用场景</strong>：相比 SSE，它更适合<strong>云原生环境</strong>，能更高效地处理多个客户端连接并支持动态变更通知。</li></ul></li><li><strong>无状态协议（Stateless）</strong><ul><li><strong>技术细节</strong>：设计上请求之间<strong>不保持会话状态</strong>，旨在简化部署并提升系统水平扩展能力。</li><li><strong>适用场景</strong>：专为<strong>微服务架构</strong>和<strong>云原生部署</strong>优化，是分布式系统追求高度灵活性时的理想选择。</li></ul></li></ol><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A[STDIO] --&gt;|进程内/本地| E[本地应用与命令行工具]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B[SSE] --&gt;|HTTP实时推送| F[传统独立进程服务]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C[可流式 HTTP] --&gt;|持久连接/取代SSE| G[现代云原生环境]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  D[无状态协议] --&gt;|无会话状态| H[微服务与分布式部署]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  E -.-&gt;|开发者调试| I[本地开发阶段]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  G -.-&gt;|高可靠通知| J[生产云系统]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  H -.-&gt;|简化扩展| J</span></span></code></pre></div><blockquote><p><strong>案例对比</strong>：</p><ul><li><strong>STDIO</strong> 模式下，服务器通常在主机应用内运行，最适合开发者在<strong>本地环境</strong>中进行工具和资源的调试。</li><li><strong>Streamable-HTTP 与无状态协议</strong> 则将服务器作为独立进程处理，通过非阻塞和无状态化设计，更好地服务于多进程、高通量的<strong>云端分布式系统</strong>。</li></ul></blockquote><hr><h3 id="思考与自测❗" tabindex="-1"><strong>思考与自测</strong>❗ <a class="header-anchor" href="#思考与自测❗" aria-label="Permalink to &quot;**思考与自测**❗&quot;">​</a></h3><p>思考问题：</p><ol><li>MCP 的三层架构如何帮助提升通信的灵活性？</li><li>Statless 的协议为何对云原生环境更友好？</li><li>Spring AI 的自动注册功能在开发过程中如何起作用？</li></ol><p>自测题：</p><ol><li>MCP SDK 提供了哪些工具调用案例？</li><li>JSON-RPC 的传输机制与哪种层次直接相关？</li><li>Spring AI 的 <code>@McpPrompt</code> 注释主要解决什么问题？</li></ol>`,42)])])}const u=t(o,[["render",r]]);export{d as __pageData,u as default};
